"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[3597],{13705:e=>{e.exports=JSON.parse('{"permalink":"/blog/performance-metrics-obsession","source":"@site/blog/2022/performance-metrics-obsession.md","title":"How I overcame my obsession with performance metrics","description":"This is the story of how I became obsessed with numbers instead of being obsessed with a product. And how I overcame that and shifted my focus to real value.","date":"2022-07-31T11:48:26.000Z","tags":[{"inline":true,"label":"Product Management","permalink":"/blog/tags/product-management"},{"inline":true,"label":"Business Analysis","permalink":"/blog/tags/business-analysis"}],"readingTime":7.39,"hasTruncateMarker":true,"authors":[],"frontMatter":{"date":"2022-07-31T11:48:26.000Z","description":"This is the story of how I became obsessed with numbers instead of being obsessed with a product. And how I overcame that and shifted my focus to real value.","slug":"performance-metrics-obsession","tags":["Product Management","Business Analysis"],"title":"How I overcame my obsession with performance metrics"},"unlisted":false,"prevItem":{"title":"Thoughts about J. Gharajedaghi\'s \\"System Thinking\\"","permalink":"/blog/reading-gharajedaghi-system-thinking"},"nextItem":{"title":"Sidekick product","permalink":"/blog/sidekick-product"}}')},28453:(e,t,a)=>{a.d(t,{R:()=>i,x:()=>r});var n=a(96540);const s={},o=n.createContext(s);function i(e){const t=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(o.Provider,{value:t},e.children)}},48185:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>d,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>n,toc:()=>h});var n=a(13705),s=a(74848),o=a(28453);const i={date:new Date("2022-07-31T11:48:26.000Z"),description:"This is the story of how I became obsessed with numbers instead of being obsessed with a product. And how I overcame that and shifted my focus to real value.",slug:"performance-metrics-obsession",tags:["Product Management","Business Analysis"],title:"How I overcame my obsession with performance metrics"},r="How I overcame my obsession with performance metrics",d={authorsImageUrls:[]},h=[{value:"Why did I fall into the \u201cnumber obsession\u201d trap?",id:"why-did-i-fall-into-the-number-obsession-trap",level:2},{value:"The Overcoming",id:"the-overcoming",level:2}];function l(e){const t={a:"a",em:"em",h2:"h2",img:"img",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:(0,s.jsx)(t.img,{alt:"Cover",src:a(70709).A+"",width:"5300",height:"3533"})}),"\n",(0,s.jsx)(t.p,{children:"I fell into a common trap of every manager: obsession with performance metrics. Since I have been promoted to the PO role my responsibilities include tracking stats related to the backlog and team performance. That includes the team\u2019s capacity, estimates, velocity, and other specific metrics. In an ideal world, the estimation of planned features matches capacity, the team performs a predicted velocity and (more importantly) delivers features in time. But we all know that doesn\u2019t work this way."}),"\n",(0,s.jsx)(t.p,{children:"This is the story of how I became obsessed with numbers instead of being obsessed with a product. And how I overcame that and shifted my focus to real value."}),"\n",(0,s.jsx)(t.h2,{id:"why-did-i-fall-into-the-number-obsession-trap",children:"Why did I fall into the \u201cnumber obsession\u201d trap?"}),"\n",(0,s.jsx)(t.p,{children:"Here are the main reasons, from my perspective:"}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Ambitions"})}),"\n",(0,s.jsx)(t.p,{children:"As a newbie Product Owner, I wanted to do my job perfectly: produce an ideal roadmap with epics and user stories that contain clear requirements so that the team could provide precise estimations (in story points). Then that would be translated into a plan fitting the team\u2019s capacity. The team would commit to the plan and complete it with flying colors within a predicted timeframe. Customers are happy, stakeholders are happy, my manager is happy, and the team is also happy. I would receive a gold medal for \u201cthe best PO of the year\u201d with a promotion to the Chief Product Officer position. Or Vice President of something, why not?"}),"\n",(0,s.jsx)(t.p,{children:"But the reality is harsh. The requirements are not always defined well, technical complexity is underestimated, the team lacks experience in some domains, dependencies on other teams, and urgent customer support requests. I named only a few obstacles - pretty sure you know the others."}),"\n",(0,s.jsxs)(t.p,{children:["So the original plan is not valid anymore, epics and features shift to \u201csomewhen when it is ready - maybe this year, maybe not\u201d. You found yourself in the hell of constant re-planning (you can read about it in ",(0,s.jsx)(t.a,{href:"/blog/product-manager-year-one",children:"one of my previos essays"}),"). You re-plan, the plan fails to meet reality, you replan again and now it looks good. Oh, f*ck, two developers left the team\u2026 Here we go again."]}),"\n",(0,s.jsx)(t.p,{children:"When you spend most of your time on re-planning, you can\u2019t be focused on the product."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Pressure"})}),"\n",(0,s.jsx)(t.p,{children:"Of course, there are reports that track those performance metrics across all the teams. Nothing bad here, this is a must-have if you want to stay on track."}),"\n",(0,s.jsx)(t.p,{children:"\u201cWhy did your team close so few story points in a previous sprint?\u201d I have been asked more and more frequently."}),"\n",(0,s.jsx)(t.p,{children:"I had a default answer. \u201cWe dragged some user stories to the next sprint due to ...(blah-blah).\u201d"}),"\n",(0,s.jsx)(t.p,{children:"That follows with something like, \u201cTake a look at this graph. You can see that you are behind the program increment plan. You should have completed this (number) of story points. But you only completed (much less) so please do something. Let me know if you need my help\u201d."}),"\n",(0,s.jsx)(t.p,{children:"That \u201cdo something\u201d implied the re-planning. \u201cSure, I will take a look and handle this\u201d."}),"\n",(0,s.jsx)(t.p,{children:"Now I understand: no one tried to assault me with those questions. Just to highlight an issue and make sure that it is on my radar. But that, multiplied by my ambitions and immaturity as a PO, built up enormous pressure inside me."}),"\n",(0,s.jsx)(t.p,{children:"I fiercely wanted those damn graphs to look good. I tried to use different approaches in feature decomposition and planning, introduced changes to the refinement process, and scheduled additional meetings to discuss any technical issues before the development. But still, non-completed tasks dragged from sprint to sprint and overlapped with new tasks. None of the original plans seemed feasible or even somehow controllable."}),"\n",(0,s.jsxs)(t.p,{children:["With all that, my old good friend, the imposter syndrome came into play. \u201cWhat if I am not a real PO? What if ",(0,s.jsx)(t.strong,{children:(0,s.jsx)(t.strong,{children:"they realize"})})," that I am not a real PO? I should have better stayed as a Business Analyst and never move to a product organization.\u201d"]}),"\n",(0,s.jsx)(t.h2,{id:"the-overcoming",children:"The Overcoming"}),"\n",(0,s.jsx)(t.p,{children:"Friday, the last day of a Sprint. About 10 PM. I am on the call with a Team Lead (TL) discussing the sprint closure. We really struggled a few previous iterations having a very low team velocity vs our quarter roadmap plans. Several big technical features were continuously dragged from sprint to sprint with multiple issues appearing along the way."}),"\n",(0,s.jsx)(t.p,{children:"But this sprint is different. We have managed to close those big features, handle a few customer requests, and fix a bunch of bugs. I did some calculations and that appeared to be our best sprint for the last 7 (!) months. The team is encouraged as it seems we have overcome that dark period."}),"\n",(0,s.jsx)(t.p,{children:"But this is not what we are talking about with TL. We are discussing 2 medium-sized features that have been developed but not yet tested. They were delivered to a testing environment late today, so our QA already ended her working day. If we could close those features right now, the sprint result will be outstanding. The team really worked hard and deserved that."}),"\n",(0,s.jsx)(t.p,{children:"\u201cWhat will we do with the features?\u201d TL asked. I am a Product Owner and I have the power to decide whether a feature is completed or needs additional work to be done."}),"\n",(0,s.jsx)(t.p,{children:"\u201cListen, those features are quite small improvements of non-critical functionality. They passed dev testing phase and I personally checked them. All works as expected. Right?\u201d I don\u2019t want to lose the outstanding number I already calculated in my mind. And I am determined to make that happen."}),"\n",(0,s.jsx)(t.p,{children:"\u201cWhat do you suggest? Close the tickets without real testing?\u201d"}),"\n",(0,s.jsx)(t.p,{children:"\u201cYes, you are right. As I said, that is not a critical functionality. I don\u2019t see any risks there. Let\u2019s set them as non-QA, close, and go rest. We did a really great job so we all deserved that\u201d, I can sound very convincing."}),"\n",(0,s.jsx)(t.p,{children:"\u201cOK, I agree\u201d."}),"\n",(0,s.jsx)(t.p,{children:"After some manipulations, the features were considered as done, the tickets were resolved and the Sprint was closed. Time to enjoy the weekend."}),"\n",(0,s.jsx)(t.p,{children:"Saturday morning I received a message from our QA Lead (QL). \u201cHi, I saw you had closed those 2 tickets as non-QA\u201d."}),"\n",(0,s.jsx)(t.p,{children:"I am ready to defend, \u201cYes. Developers finished them very late so you were already off. They are quite small so I decided to complete them as non-QA\u201d."}),"\n",(0,s.jsx)(t.p,{children:"\u201cOK. I just wondering, do we need to cover them with automated tests?\u201d"}),"\n",(0,s.jsx)(t.p,{children:"F*ck. We\u2019d better cover them with autotests. But that means the QA team needs to write testing scenarios, validate them, and then proceed with automation. Basically, to do the work I previously defined as \u201cnot needed\u201d by converting the features to non-QA."}),"\n",(0,s.jsx)(t.p,{children:"I take a pause. There is a growing feeling that I have done something very stupid. I manipulated with features and moved testing activities in \u201ca shadow mode\u201d to the next Sprint and proudly announced that they are completed. But they are not. I start feeling sick."}),"\n",(0,s.jsx)(t.p,{children:"\u201cYes, we need to automate both features\u201d, it took me about 30 minutes to answer her."}),"\n",(0,s.jsx)(t.p,{children:"\u201cOK, no problem. Next week I will pass it to the QA team and we will proceed with the automation. Have a nice weekend!\u201d"}),"\n",(0,s.jsx)(t.p,{children:"That weekend was not nice for me at all. I passed through the Five stages \u2013 denial, anger, bargaining, depression, and acceptance. I fought with my ego which was obsessed with the numbers and wanted to achieve high results, even fictional, at any cost."}),"\n",(0,s.jsx)(t.p,{children:"Next Monday we had a team retrospective call. I apologized to the entire team. I confessed that I manipulated tickets for the only reason to satisfy my ego with good stats. I spoiled a really great team achievement and now QAs had to cover my ass with that testing."}),"\n",(0,s.jsx)(t.p,{children:"\u201cWhat I did is stupid. I am really sorry. I will never do that again\u201d."}),"\n",(0,s.jsx)(t.p,{children:"And I am keeping my promise. Now, by the end of each Sprint, I consider only what is really done. I am no longer pushing tickets for good stats. I don\u2019t really know how many story points my team closed last sprint or earlier. I am smiling when some managers report something like \u201cWe completed 1000 story points during a last sprint/quarter/year\u201d. I am no longer playing that game."}),"\n",(0,s.jsx)(t.p,{children:"I am focused on the value we, as the Team, can produce for our customers. We can do a complex functionality during a few iterations and that will not look good on reports. But when we deliver that might have a big positive impact on those who use our services. Value can be transitioned to customer satisfaction and that can be transitioned to profits. Story points do not transition to value."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"Take care,"})}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"Ilya"})}),"\n",(0,s.jsx)("small",{children:(0,s.jsx)("a",{href:"https://www.vecteezy.com/free-vector/meditation",children:"Meditation Vectors by Vecteezy"})})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},70709:(e,t,a)=>{a.d(t,{A:()=>n});const n=a.p+"assets/images/Meditation-Man-Working-1b2af9a20e7ff2da2c675d6f15b1a686.jpg"}}]);